with cleaned as (select *, cast(quantity as string) quantity_num from inventory where last_restock >= date '2023-04-28' and product_id in (2, 5, 7, 9)) select *, row_number() over (partition by product_id order by last_restock desc, id) row_seq, sum(quantity) over (partition by store_id order by last_restock, id rows between unbounded preceding and current row) cumulative_quantity, rank() over w_running quantity_rank from cleaned window w_running as (partition by store_id order by quantity nulls last)
